import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source implementing a per‑row cumulative sum for fp16 tensors.
# Accumulation is performed in float32 for higher precision.
cpp_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

// -----------------------------------------------------------------------------
// Kernel: each thread processes one "line" (i.e. one slice along the scan axis)
// -----------------------------------------------------------------------------
__global__ void cumsum_fp16_kernel(const half* __restrict__ in,
                                   half* __restrict__ out,
                                   int size_dim,
                                   int lines) {
    int line = blockIdx.x * blockDim.x + threadIdx.x;
    if (line >= lines) return;

    const half* in_line  = in + line * size_dim;
    half*       out_line = out + line * size_dim;

    float acc = 0.0f;
    for (int i = 0; i < size_dim; ++i) {
        acc += __half2float(in_line[i]);          // promote to float32
        out_line[i] = __float2half(acc);           // store back as fp16
    }
}

// -----------------------------------------------------------------------------
// C++ entry point invoked from Python
// -----------------------------------------------------------------------------
void cumsum_fp16(torch::Tensor input,
                 torch::Tensor output,
                 int64_t size_dim,
                 int64_t lines) {
    const int threads = 256;
    const int blocks = (lines + threads - 1) / threads;

    AT_ASSERTM(input.is_cuda(),    "input must be a CUDA tensor");
    AT_ASSERTM(output.is_cuda(),   "output must be a CUDA tensor");
    AT_ASSERTM(input.dtype() == torch::kHalf,  "input must be torch.float16");
    AT_ASSERTM(output.dtype() == torch::kHalf, "output must be torch.float16");

    cumsum_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<half*>(input.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        static_cast<int>(size_dim),
        static_cast<int>(lines));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}

// -----------------------------------------------------------------------------
// PyBind11 binding
// -----------------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cumsum_fp16", &cumsum_fp16, "Cumulative sum along a dimension (fp16, CUDA)");
}
'''

# Compile the inline extension (the harness will provide the proper C++ standard flag)
cumsum_mod = load_inline(name='cumsum_fp16_ext',
                         cpp_sources=cpp_source,
                         functions=['cumsum_fp16'],
                         verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.  Performs a cumulative sum
    (prefix sum) along the user‑specified dimension using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure contiguous fp16 CUDA tensor
        if not x.is_contiguous():
            x = x.contiguous()
        assert x.is_cuda, "Input must be on CUDA"
        assert x.dtype == torch.float16, "Input must be torch.float16"

        # Collapse all dimensions except the scan axis into a 2‑D view:
        #   (num_lines, size_dim)
        size_dim = x.size(self.dim)
        total_elems = x.numel()
        lines = total_elems // size_dim

        # Allocate output tensor
        out = torch.empty_like(x)

        # Launch the kernel
        cumsum_mod.cumsum_fp16(x, out, size_dim, lines)

        return out

# -------------------------------------------------------------------------
# Helper functions matching the original harness API
# -------------------------------------------------------------------------
def get_inputs():
    """
    Generates a random fp16 CUDA tensor matching the reference dimensions:
    (batch_size, input_dim) with batch_size = 32768 and input_dim = 32768.
    """
    batch_size = 32768
    input_dim = 32768
    return [torch.rand(batch_size, input_dim, dtype=torch.float16, device='cuda')]

def get_init_inputs():
    """
    Returns the initialization argument list for ModelNew.
    The reference uses dim = 1 (cumulative sum along the second axis).
    """
    return [1]
